CREATE POLICY "patient_files_clinica_read" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'patient-files' AND public.can_access_row((storage.foldername(name))[1]::uuid));
CREATE POLICY "patient_files_clinica_insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'patient-files' AND public.can_access_row((storage.foldername(name))[1]::uuid));
CREATE POLICY "patient_files_clinica_update" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'patient-files' AND public.can_access_row((storage.foldername(name))[1]::uuid));
CREATE POLICY "patient_files_clinica_delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'patient-files' AND public.can_access_row((storage.foldername(name))[1]::uuid));